{"code": "const script = String.raw`#!/usr/bin/env python3
"""Board-only fast path for the J08-lite coprocessor loader.

This deliberately does NOT call the packaged loader's prepare_board()/run_board():
that path pulses SLCR FPGA_RST_CTRL, whose readback is 0 on this board, so it can
assert FCLK0/AXI resets as well and hang the PS.  It also does not use the packaged
level-sensitive dma_start write, which can retrigger after the CDC ack and abort the
adapter.

Flow:
  1. preflight manifest/HWH/SHA BEFORE resetting PL;
  2. FCLK1=40, Overlay the package bit/hwh;
  3. write config, push payload/ROI DMA with a tiny C start-pulse helper;
  4. read ACCEPTED/terminal/result and persist the measurement JSON.

Run ON THE BOARD as root with the PYNQ venv:
  sudo -E /usr/local/share/pynq-venv/bin/python3 \
    sim/scripts/cop_board_fast_run.py --package /home/xilinx/cop-pkg-newbit \
    --case zero --measurement /tmp/zero-fast.json
"""
import argparse
import inspect
import json
import os
import subprocess
import sys
import time
from pathlib import Path

C_SOURCE = r"""#include <fcntl.h>
#include <stdint.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <unistd.h>
int main(int argc, char **argv) {
    if (argc != 2) return 2;
    int kind = atoi(argv[1]) & 1;
    int fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (fd < 0) return 3;
    volatile uint32_t *p = mmap(NULL, 0x1000, PROT_READ | PROT_WRITE,
                                MAP_SHARED, fd, 0x40020000);
    if (p == MAP_FAILED) { close(fd); return 4; }
    uint32_t ctl = ((uint32_t)kind) << 1;
    p[0] = ctl | 1u;
    p[0] = ctl;
    __sync_synchronize();
    munmap((void *)p, 0x1000);
    close(fd);
    return 0;
}
"""


def build_helper(path="/tmp/cop_fast_start"):
    source = path + ".c"
    for candidate in (source, path):
        try:
            os.unlink(candidate)
        except FileNotFoundError:
            pass
    with open(source, "w", encoding="utf-8") as stream:
        stream.write(C_SOURCE)
    subprocess.run(["gcc", "-O2", "-Wall", "-o", path, source], check=True)
    return path


def make_fast_send(loader, helper):
    def fast_start(kind):
        result = subprocess.run([helper, str(kind)], check=False)
        if result.returncode != 0:
            raise loader.LoaderError("fast_start failed rc=%d" % result.returncode)

    def fast_send(dma, gpio, cop, buffer, length, kind, timeout):
        if length < 1 or length > loader.DMA_LENGTH_MAX:
            raise loader.LoaderError("DMA length does not fit 16-bit")
        if not gpio.read(loader.GPIO2_DATA) & 1:
            raise loader.LoaderError("start_ready is 0 before dma_start")
        gpio.write(loader.GPIO_TRI, 0)
        gpio.write(loader.GPIO2_TRI, 0xFFFFFFFF)
        fast_start(kind)
        loader.wait_for(
            lambda: loader.read_mask(cop, loader.REG["STATUS"], loader.STATUS["DMA_BUSY"]),
            timeout, "start request not accepted")
        buffer.flush()
        dma.write(loader.DMA_DMACR, 4)
        loader.wait_for(lambda: 1 if not dma.read(loader.DMA_DMACR) & 4 else None,
                        timeout, "AXI DMA reset timeout")
        dma.write(loader.DMA_DMACR, 1)
        dma.write(loader.DMA_SA, int(buffer.physical_address))
        dma.write(loader.DMA_LENGTH, length & loader.DMA_LENGTH_MAX)
        seen_payload_error = False

        def transfer_done():
            nonlocal seen_payload_error
            seen_payload_error |= bool(gpio.read(loader.GPIO2_DATA) & 2)
            status = dma.read(loader.DMA_DMASR)
            if status & 0x770:
                raise loader.LoaderError("AXI DMA MM2S error status=0x%08x" % status)
            return status if status & 2 else None

        transfer_status = loader.wait_for(transfer_done, timeout, "AXI DMA MM2S timeout")
        loader.wait_for(
            lambda: loader.read_mask(cop, loader.REG["STATUS"], loader.STATUS["DMA_BUSY"], False),
            timeout, "coprocessor DMA loader did not finish")
        gpio_status = gpio.read(loader.GPIO2_DATA)
        if seen_payload_error or gpio_status & 2:
            raise loader.LoaderError("payload_error observed")
        if not gpio_status & 1:
            raise loader.LoaderError("start_ready did not return")
        if cop.read(loader.REG["DMA_BYTES"]) != length:
            raise loader.LoaderError("DMA_BYTES differs from submitted byte count")
        return transfer_status
    return fast_send


def run_one(loader, package, case, measurement, timeout, pre, fast_send):
    from pynq import MMIO, allocate

    manifest, payload, roi, expected, caps = pre
    cop = MMIO(loader.COP_BASE, 0x1000)
    dma = MMIO(loader.DMA_BASE, 0x10000)
    gpio = MMIO(loader.GPIO_BASE, 0x10000)
    initial = cop.read(loader.REG["STATUS"])
    if initial & loader.STATUS["UNCONSUMED"]:
        raise loader.LoaderError("STALE_RESULT status=0x%08x" % initial)

    buffers = {name: allocate(shape=(size,), dtype="u1") for name, size in
               (("payload", len(payload)), ("roi", len(roi)),
                ("targets", 64), ("results", 256))}
    try:
        buffers["payload"][:] = list(payload)
        buffers["roi"][:] = list(roi)
        buffers["targets"][:] = 0
        buffers["results"][:] = 0
        buffer_flush = [buffers[name].flush for name in buffers]

        sequence_before = cop.read(loader.REG["RESULT_SEQ"])
        sequence = int(time.time()) & 0xFFFFFFFF or 1
        params = inspect.signature(loader.write_configuration).parameters
        if "expected" in params:
            loader.write_configuration(cop, manifest, expected, buffers, sequence)
        else:
            loader.write_configuration(cop, manifest, case, buffers, sequence)
        loader.dma_send = fast_send
        loader.dma_send(dma, gpio, cop, buffers["payload"], len(payload), 0, timeout)
        loader.dma_send(dma, gpio, cop, buffers["roi"], len(roi), 1, timeout)
        measured = loader.read_result(cop, expected, sequence_before, timeout)
        measured.update({"case": case,
                         "fclk1_mhz": float(__import__("pynq").Clocks.fclk1_mhz),
                         "payload_bytes": len(payload),
                         "payload_crc32": manifest["crc32"],
                         "dma_stream_bits": caps["stream_bits"]})
        output = Path(measurement).resolve()
        temporary = output.with_name(output.name + ".tmp")
        with temporary.open("wb") as stream:
            stream.write((json.dumps(measured, sort_keys=True) + "\n").encode("utf-8"))
            stream.flush()
            os.fsync(stream.fileno())
        temporary.replace(output)
        print(json.dumps(measured, sort_keys=True))
        print("measurement_file=" + str(output))
        if not measured.get("matches_expected"):
            raise loader.LoaderError("measurement does not match EXPECTED_OUTPUTS.tsv")
    finally:
        for buffer in buffers.values():
            try:
                buffer.freebuffer()
            except Exception:
                pass


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--package", required=True)
    parser.add_argument("--case", required=True)
    parser.add_argument("--measurement", required=True)
    parser.add_argument("--timeout", type=float, default=10.0)
    parser.add_argument("--helper", default="/tmp/cop_fast_start")
    args = parser.parse_args()

    package = os.path.abspath(args.package)
    sys.path.insert(0, os.path.join(package, "payload", "tools"))
    import cop_payload_loader as loader
    from pynq import Clocks, Overlay

    # Slow file/HWH preflight BEFORE the PL reset starts the firmware wait window.
    pre = loader.preflight(package, args.case)
    helper = build_helper(args.helper)
    fast_send = make_fast_send(loader, helper)

    Clocks.fclk1_mhz = 40.0
    overlay = Overlay(os.path.join(package, "payload", "pynq_cop_40mhz.bit"))
    run_one(loader, package, args.case, args.measurement, args.timeout, pre, fast_send)
    return overlay


if __name__ == "__main__":
    main()
`;
